import{z as s,x as t,o as B,c as p,q as i,j as l,D as e,d as a,s as o,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"高性能网络收束","description":"","frontmatter":{"title":"高性能网络收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-map.md","filePath":"cs/hpc-map.md","lastUpdated":1791413859000}'),D={name:"cs/hpc-map.md"};function d(C,E,c,h,P,_){const r=t("Mermaid");return B(),p("div",null,[E[2]||(E[2]=i('<h1 id="高性能网络收束" tabindex="-1">高性能网络收束 <a class="header-anchor" href="#高性能网络收束" aria-label="Permalink to &quot;高性能网络收束&quot;">​</a></h1><div class="epigraph"><p>每下移一层路径，就把内核替你做的一件事接过来自己做；选型是用运维复杂度买延迟与包率。</p><footer>—— 据 io_uring、DPDK、AF_XDP、RDMA 各自官方文档的取舍陈述整理</footer></div><p><a href="/cs/hpc-zerocopy-latency">上一课</a>把零拷贝的收益与测量的纪律钉在一起：先知道省在哪，再谈省了多少。本课程到此收束：本课把五课的路径拼成一张选型账，明确每条路径适合的负载、真实代价与失败方式，最后收在共同原理上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>决策变量从来不是「哪个最快」，而是四个：每秒事件与包数、消息大小、延迟预算与尾部要求、可接受的复杂度。<a href="/cs/hpc-epoll-deep">课程第一课</a>的分片事件循环覆盖万级连接的通用服务，内核全托管，代价最小；</p><p><span class="marginnote">术语翻译：「陷入」（trap）就是用户态程序每次请内核办事的一次往返——保存现场、切进内核、办完再回来。epoll 模式下每个就绪事件至少来回两趟，这笔按次收取的「固定税」正是 io_uring 与旁路方案要摊销的东西。</span><a href="/cs/hpc-io-uring">io_uring</a> 在陷入次数成为瓶颈时接管批量 I/O，代价是版本碎片与攻击面；AF_XDP 在包率逼近线速、协议栈每包处理本身成为成本时介入；<a href="/cs/hpc-kernel-bypass">内核旁路：DPDK 与 AF_XDP</a> 的完整旁路在核可专用时换线速与窄分布；<a href="/cs/hpc-rdma">RDMA</a> 在跨机带宽与延迟成为瓶颈、且有专用网络时把对端操作系统也请出局。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型按瓶颈位置走，先测后选：卡在系统调用次数 → io_uring；卡在协议栈每包成本 → AF_XDP；卡在核与缓存亲和 → DPDK；卡在跨机带宽延迟 → RDMA。动手下移之前，按上一课的测量纪律拿到可信的延迟分布与每包成本，否则选型本身就在未测量的假设上进行。五条路径的共同原理是摊销每事件固定成本：批处理摊陷入，核亲和摊缓存失效，专用无损网络摊重传——每下移一层，都是把「每次都付的固定税」改写成「一次付清的固定成本」。</p>',8)),(B(),l(n,null,{default:e(()=>[o(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%93%B6%E9%A2%88%E5%9C%A8%E5%93%AA%EF%BC%9F%22%5D%20--%3E%20SYS%5B%22%E9%99%B7%E5%85%A5%E6%AC%A1%E6%95%B0%E9%AB%98%22%5D%0A%20%20Q%20--%3E%20PKT%5B%22%E5%8D%8F%E8%AE%AE%E6%A0%88%E6%AF%8F%E5%8C%85%E6%88%90%E6%9C%AC%E9%AB%98%22%5D%0A%20%20Q%20--%3E%20CORE%5B%22%E6%A0%B8%E4%B8%8E%E7%BC%93%E5%AD%98%E5%A4%B1%E9%85%8D%22%5D%0A%20%20Q%20--%3E%20CROSS%5B%22%E8%B7%A8%E6%9C%BA%E5%B8%A6%E5%AE%BD%E5%BB%B6%E8%BF%9F%E5%8D%A1%22%5D%0A%20%20SYS%20--%3E%20IOU%5B%22io_uring%EF%BC%9A%E6%89%B9%E9%87%8F%E6%8F%90%E4%BA%A4%E4%B8%8E%E6%94%B6%E5%89%B2%22%5D%0A%20%20PKT%20--%3E%20XDP%5B%22AF_XDP%EF%BC%9A%E9%A9%B1%E5%8A%A8%E5%B1%82%E5%88%86%E8%AF%8A%22%5D%0A%20%20CORE%20--%3E%20DPDK%5B%22DPDK%EF%BC%9APMD%20%E7%8B%AC%E5%8D%A0%E6%A0%B8%E8%BD%AE%E8%AF%A2%22%5D%0A%20%20CROSS%20--%3E%20RDMA%5B%22RDMA%EF%BC%9A%E4%BC%A0%E8%BE%93%E8%BF%9B%E7%BD%91%E5%8D%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("下移的机制含义：内核职责不会消失，只会改名。错误处理从内核协议栈变成应用状态机；流控从 TCP 窗口变成 PFC 或应用背压；统计从 netns 计数器变成自建计数器；安全边界从系统调用层变成要审计的用户态代码。选型错误也各有名字：用未分片的 epoll 跑线速，扫描与陷入淹没 CPU；用 DPDK 跑凌晨低峰，轮询烧核；用 RoCE 却不管 PFC 配置，无损网络自己死锁；只报平均延迟，尾部问题被平均掉。量化栏的"),A("a",{href:"/quant/colocation-microwave"},"主机托管与微波"),a("是这张阶梯在另一栏的极端读者：软件路径走到尽头后，剩下的延迟在光纤与微波里——那是物理的账，不在本课程之内。")],-1)),E[5]||(E[5]=A("p",null,"「改名」具体怎么改？把内核托管与旁路之后各职责的去向对照着看：",-1)),(B(),l(n,null,{default:e(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20N%5B%22%E5%86%85%E6%A0%B8%E6%89%98%E7%AE%A1%EF%BC%88epoll%EF%BC%89%22%5D%0A%20%20%20%20TCP%5B%22TCP%20%E7%AA%97%E5%8F%A3%E7%AE%A1%E6%B5%81%E6%8E%A7%22%5D%0A%20%20%20%20STAT%5B%22%E5%86%85%E6%A0%B8%E8%AE%A1%E6%95%B0%E5%99%A8%E5%87%BA%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20%20%20SEC%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E5%B1%82%E5%81%9A%E5%AE%89%E5%85%A8%E8%BE%B9%E7%95%8C%22%5D%0A%20%20end%0A%20%20subgraph%20B%5B%22%E4%B8%8B%E7%A7%BB%E4%B9%8B%E5%90%8E%EF%BC%88%E6%97%81%E8%B7%AF%EF%BC%89%22%5D%0A%20%20%20%20BP%5B%22%E5%BA%94%E7%94%A8%E7%8A%B6%E6%80%81%E6%9C%BA%E7%AE%A1%E9%87%8D%E4%BC%A0%E4%B8%8E%E8%83%8C%E5%8E%8B%22%5D%0A%20%20%20%20SC%5B%22%E8%87%AA%E5%BB%BA%E8%AE%A1%E6%95%B0%E5%99%A8%E5%B9%B6%E8%87%AA%E8%A1%8C%E5%AF%BC%E5%87%BA%22%5D%0A%20%20%20%20AUD%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E4%BB%A3%E7%A0%81%E8%87%AA%E6%8B%85%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20end%0A%20%20TCP%20--%3E%20BP%0A%20%20STAT%20--%3E%20SC%0A%20%20SEC%20--%3E%20AUD%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">数量级锚点：就绪通知每事件 2 次陷入；io_uring 批量摊销后不足 1 次；DPDK 把每包压进数百纳秒但独占核；RDMA 同机房 RTT 约 1–2 μs。跨栏对照：量化交易的托管与微波把「路径长度」当预算，与本课程同一套逻辑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不写具体服务框架（nginx、Envoy、Seastar）的选型对照，不写云网络虚拟化的数据面，不进入传输层协议细节的再推导；旁路方案的安全与调试代价是选型的一等输入，不是脚注。本课程到此收束。</p><p><span class="marginnote">常见误区：只看平均延迟。均值 100 μs 听着不错，但若 p99 是 2 ms，等于每 100 个请求就有 1 个慢 20 倍——在交易与广告竞价里，这一小撮恰恰是盈亏分界。选型依据必须是分位数，不是均值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选型按瓶颈位置：陷入 → io_uring，每包成本 → AF_XDP/DPDK，跨机 → RDMA；先测后选。</li><li>每下移一层，内核职责改名由你承担：状态机、背压、计数器、安全审计。</li><li>旁路与零拷贝是负载形态的函数：低包率轮询更贵，小包零拷贝更贵。</li><li>测量纪律先于优化：打点位置、残余钟差、尾部分位，缺一项结论不成立。</li><li>从软件路径再往下，延迟在光纤与微波里；那是物理的账，不属本课程。</li><li>出处：Linux epoll/io_uring/AF_XDP/RDMA 各自文档；DPDK 文档；据各官方取舍陈述整理。</li></ul><p><span class="marginnote">直觉类比：五条路径像通勤方式——epoll 是公交（便宜、拥挤但省心），io_uring 是拼车（几件事合一次出行分摊固定费），DPDK 是包一辆专车（随叫随到，空驶也得付车钱），RDMA 是两端直达的专线（路上不堵，但要先修轨道）。没有最好，只有跟负载合不合身。</span></p>',7))])}const F=s(D,[["render",d]]);export{m as __pageData,F as default};
